            Q[i][j] = f[(i << (n - 1)) | (j << (n - 2))]
            if i != j:
                Q[j][i] = Q[i][j]
    return sum(Q[i][j] * x_k[i] * x_k[j] for i in range(n) for j in range(i, n))

def minimal_quadratic_defect(f):
    n = int(math.log2(len(f)))
